function makePrefSumNonNegative(nums) {
  // Breadth-first search over every arrangement reachable by moving one element to the end.
  const fine = (arr) => {
    let total = 0;
    for (const v of arr) {
      total += v;
      if (total < 0) return false;
    }
    return true;
  };
  let frontier = [nums.slice()];
  const seen = new Set([nums.join(',')]);
  for (let steps = 0; frontier.length > 0; steps++) {
    const next = [];
    for (const arr of frontier) {
      if (fine(arr)) return steps;
      for (let i = 0; i < arr.length; i++) {
        const moved = [...arr.slice(0, i), ...arr.slice(i + 1), arr[i]];
        const key = moved.join(',');
        if (!seen.has(key)) {
          seen.add(key);
          next.push(moved);
        }
      }
    }
    frontier = next;
  }
  return -1;
}

