function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  for (;;) {
    let nums;
    if (size === 'small') {
      const n = int(1, 7);
      const span = rand() < 0.2 ? 1000000000 : 9;
      nums = Array.from({ length: n }, () => int(-span, span));
      if (rand() < 0.3) nums.sort((a, b) => a - b);
    } else {
      const mode = int(0, 2);
      const span = mode === 2 ? 1000 : 1000000000;
      nums = Array.from({ length: 2000 }, () => int(-span, span));
      // Mode 1 puts every negative value first, so most of them must be moved.
      if (mode === 1) nums.sort((a, b) => a - b);
    }
    // The problem guarantees a non-negative total; retry until it holds.
    if (nums.reduce((a, b) => a + b, 0) >= 0) return [nums];
  }
}
